<?php

declare(strict_types=1);

/**
 * Template for config/system/additional.php in DDEV projects.
 *
 * bin/create-system.sh copies this file to additional.php (not versioned).
 * Based on the file generated by DDEV, without its marker comment,
 * so DDEV does not overwrite it. In addition, the MCP server of in2mcp is
 * enabled — only locally, never on staging or production.
 */
if (getenv('IS_DDEV_PROJECT') == 'true') {
    $ddevConfig = [
        // This GFX configuration allows processing by installed ImageMagick 6
        'GFX' => [
            'processor' => 'ImageMagick',
            'processor_path' => '/usr/bin/',
            'processor_path_lzw' => '/usr/bin/',
        ],
        // This mail configuration sends all emails to mailpit
        'MAIL' => [
            'transport' => 'smtp',
            'transport_smtp_encrypt' => false,
            'transport_smtp_server' => 'localhost:1025',
        ],
        'SYS' => [
            'trustedHostsPattern' => '.*.*',
            'devIPmask' => '*',
            'displayErrors' => 1,
        ],
        // MCP server of in2mcp (endpoint /typo3/mcp), only enabled locally
        'EXTENSIONS' => [
            'in2mcp' => [
                'mcpServer' => '1',
                // File import by url, restricted to the Lucide icons on GitHub
                'fileImport' => '1',
                'fileImportAllowedHosts' => 'raw.githubusercontent.com',
            ],
        ],
    ];

    // Only override the database connection if the project uses a driver
    // provided by the DDEV db container. If the Default connection has been
    // configured for anything else (like SQLite), leave it alone.
    $ddevDriver = $GLOBALS['TYPO3_CONF_VARS']['DB']['Connections']['Default']['driver'] ?? 'mysqli';
    if (in_array($ddevDriver, ['mysqli', 'pdo_mysql', 'pdo_pgsql'], true)) {
        $ddevConfig['DB'] = [
            'Connections' => [
                'Default' => [
                    'dbname' => 'db',
                    'driver' => 'mysqli',
                    'host' => 'db',
                    'password' => 'db',
                    'port' => 3306,
                    'user' => 'db',
                ],
            ],
        ];
    }

    $GLOBALS['TYPO3_CONF_VARS'] = array_replace_recursive(
        $GLOBALS['TYPO3_CONF_VARS'],
        $ddevConfig
    );
    unset($ddevConfig, $ddevDriver);
}
